package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={PdfCanvasHost.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Library513Test {
    WorkTestSupport w;@Before public void setup()throws Exception{w=new WorkTestSupport();}@After public void close(){w.close();}
    @Test public void changingMetadataPreservesAnAssociationOutsideTheFirst500Collections()throws Exception{String hash=String.join("",Collections.nCopies(64,"b"));long last=0,first=0;try(PlusStore db=new PlusStore(w.app)){db.getWritableDatabase().beginTransaction();try{for(int i=0;i<501;i++){long id=BookCategories.collection(db,String.format(Locale.ROOT,"Colecção %04d",i));if(i==0)first=id;last=id;}db.save("book_collections",StudyStore.values("hash",hash,"collection",last));db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}}Map<Long,Boolean> edits=new HashMap<>();edits.put(first,true);BookCategories.saveChanges(w.app,hash,"Ciência","Série A","",edits);try(PlusStore db=new PlusStore(w.app)){assertTrue(db.hashes("collection",""+last).contains(hash));assertTrue(db.hashes("collection",""+first).contains(hash));assertEquals("Ciência",db.rows("book_meta","hash=?",new String[]{hash},null,1).get(0).s("topic"));}edits.put(first,false);BookCategories.saveChanges(w.app,hash,"Outro assunto","Série B","",edits);try(PlusStore db=new PlusStore(w.app)){assertTrue(db.hashes("collection",""+last).contains(hash));assertFalse(db.hashes("collection",""+first).contains(hash));}}
    @Test public void revisionSearchCanSelectTheOldestOf250Notes()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();long subject;try(StudyStore db=new StudyStore(a)){subject=db.save("subjects",0,StudyStore.values("title","Módulo","color",0,"created",1));for(int i=0;i<250;i++)db.save("notes",0,StudyStore.values("subject",subject,"title","Nota "+i,"body","Conteúdo "+i,"created",i+1,"updated",i+1));db.save("questions",0,StudyStore.values("subject",subject,"prompt","Pergunta?","answer","Resposta.","updated",300));}RevisionNotebook book=new RevisionNotebook(a,"",0,subject,"Módulo");RevisionNotebook.Page page=book.page("",240,40);assertEquals(251,page.total);assertTrue(page.rows.stream().anyMatch(item->item.title.equals("Nota 0")));RevisionNotebook.Page found=book.page("Nota 0",0,40);assertEquals(1,found.total);assertEquals("Conteúdo 0",book.body(found.rows.get(0)));assertTrue(book.choices().stream().anyMatch(item->item.kind.equals("Pergunta")));a.finish();}
    @Test public void selectingAllInOneRevisionSearchDoesNotSelectUnrelatedLaterResults()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();try{try(StudyStore db=new StudyStore(a)){for(String title:new String[]{"Álgebra A","Álgebra B","Biologia"})db.save("notes",0,StudyStore.values("title",title,"body",title,"created",1,"updated",1));}RevisionPicker picker=new RevisionPicker(new RevisionNotebook(a,"",0,0,"Revisão"));picker.show();picker.query.setText("Álgebra");picker.selectAll();PlusUi.LONG.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();PlusUi.WORK.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(2,picker.selectedCount());picker.query.setText("Biologia");picker.load();PlusUi.WORK.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,picker.list.getAdapter().getCount());android.widget.CheckBox row=(android.widget.CheckBox)picker.list.getAdapter().getView(0,null,picker.list);assertFalse(row.isChecked());assertEquals(2,picker.selectedCount());row.setChecked(true);assertEquals(3,picker.selectedCount());}finally{UiDialog.dismissAll(a);a.finish();}}
    @Test public void revisionWriterRollsIntoVolumesInsteadOfDroppingLaterPages()throws Exception{List<byte[]> volumes=new ArrayList<>();try(RevisionNotebook.PdfWriter pdf=new RevisionNotebook.PdfWriter("Revisão",number->new ByteArrayOutputStream(){boolean recorded;public void close()throws IOException{if(!recorded){recorded=true;volumes.add(toByteArray());}super.close();}},2)){pdf.heading("Primeira parte");pdf.page();pdf.heading("Segunda parte");pdf.page();pdf.heading("Terceira parte");try(ByteArrayOutputStream out=new ByteArrayOutputStream()){pdf.write(out);volumes.add(out.toByteArray());}}assertEquals(2,volumes.size());try(com.tom_roush.pdfbox.pdmodel.PDDocument first=com.tom_roush.pdfbox.pdmodel.PDDocument.load(volumes.get(0));com.tom_roush.pdfbox.pdmodel.PDDocument last=com.tom_roush.pdfbox.pdmodel.PDDocument.load(volumes.get(1))){assertEquals(2,first.getNumberOfPages());assertEquals(1,last.getNumberOfPages());}assertTrue(PdfCanvasHost.text.stream().anyMatch(s->s.contains("Terceira parte")));}
    @Test public void epubTitleAuthorAndSeriesAreReadWithoutChangingTheContainer()throws Exception{File file=new File(w.app.getCacheDir(),"metadata.epub");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(file))){ChapterExportTest.entry(zip,"META-INF/container.xml","<container xmlns='urn:oasis:names:tc:opendocument:xmlns:container'><rootfiles><rootfile full-path='book.opf'/></rootfiles></container>");ChapterExportTest.entry(zip,"book.opf","<package xmlns:dc='http://purl.org/dc/elements/1.1/'><metadata><dc:title>Livro de Física</dc:title><dc:creator>Ana Carlos</dc:creator><meta property='belongs-to-collection'>Ciência</meta></metadata></package>");}byte[] original=Files.readAllBytes(file.toPath());BookMetadata metadata=BookMetadata.read(w.app,file,"arquivo_123.epub","application/epub+zip");assertEquals("Livro de Física",metadata.title);assertEquals("Ana Carlos",metadata.author);assertEquals("Ciência",metadata.series);assertArrayEquals(original,Files.readAllBytes(file.toPath()));}
    @Test public void repeatedMetadataWorkUsesItsOriginalTitleSnapshot()throws Exception{long book=w.book("Título.txt","Texto.");String hash=w.book(book).s("hash");String id=w.job("metadata",new JSONObject().put("prefix","Curso").put("author_set",true).put("author","Autora").put("series_set",true).put("series","Série"));try(TaskStore db=new TaskStore(w.app)){db.add(id,0,hash,"Título",0,0);}w.run(id);try(TaskStore db=new TaskStore(w.app)){db.item(id,0,StudyStore.values("state","pending"));}w.run(id);assertEquals("Curso Título",w.book(book).s("title"));assertEquals("Autora",w.book(book).s("author"));assertTrue(BookSettings.get(w.app,hash).getBoolean("manual_title"));}
    @Test public void ftsFindsAccentedContentAndTracksTheSourcePageAndOffset()throws Exception{try(LibrarySearchStore db=new LibrarySearchStore(w.app)){db.scope();db.start(4,String.join("",Collections.nCopies(64,"a")),3);db.part(4,2,"Uma explicação sobre oração e compreensão.",false);try(Cursor result=db.getReadableDatabase().rawQuery("SELECT s.part,s.start FROM texts JOIN segments s ON s.id=texts.docid WHERE texts MATCH ?",new String[]{LibrarySearchStore.match("oracao compreensao")})){assertTrue("FTS counts: "+android.database.DatabaseUtils.longForQuery(db.getReadableDatabase(),"SELECT COUNT(*) FROM segments",null)+"; accented "+android.database.DatabaseUtils.longForQuery(db.getReadableDatabase(),"SELECT COUNT(*) FROM texts WHERE texts MATCH ?",new String[]{"oração"})+"; plain "+android.database.DatabaseUtils.longForQuery(db.getReadableDatabase(),"SELECT COUNT(*) FROM texts WHERE texts MATCH ?",new String[]{"oracao"}),result.moveToFirst());assertEquals(2,result.getInt(0));assertEquals(0,result.getInt(1));assertFalse(result.moveToNext());}w.app.getSharedPreferences("reading_tools",0).edit().putString("workspace_id","restored").apply();db.scope();try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM segments",null)){count.moveToFirst();assertEquals(0,count.getInt(0));}}}
    @Test public void onePageIndexCommitCanResumeAfterTheProcessStops()throws Exception{try(LibrarySearchStore db=new LibrarySearchStore(w.app)){db.scope();db.start(3,String.join("",Collections.nCopies(64,"c")),4);db.part(3,0,"Primeira página",false);}try(LibrarySearchStore reopened=new LibrarySearchStore(w.app)){assertEquals(1,reopened.document(3).n("next_part"));reopened.part(3,1,"Segunda página",false);assertEquals(2,reopened.document(3).n("next_part"));}}
    @Test public void perBookProfilesKeepTheirVoiceBackgroundAndPauseChoices()throws Exception{File dir=new File(w.app.getFilesDir(),"backgrounds");dir.mkdirs();File background=new File(dir,"music.audio");Files.write(background.toPath(),new byte[]{1});String hash=String.join("",Collections.nCopies(64,"d"));JSONObject profile=new JSONObject().put("engine","com.google.android.tts").put("voice","selected-voice").put("language","en").put("online",true).put("rate",1.2).put("pause_ms",4000).put("background_path",background.getPath()).put("background_volume",23).put("background_enabled",true);BookSettings.update(w.app,hash,value->value.put("profile",profile));ReadingProfiles.apply(w.app,BookSettings.get(w.app,hash).getJSONObject("profile"));assertEquals("selected-voice",w.app.getSharedPreferences("seeky",0).getString("speech_voice",""));assertEquals(4000,w.app.getSharedPreferences("seeky",0).getInt("speech_title_pause_ms",0));assertEquals(23,w.app.getSharedPreferences("reading_background",0).getInt("volume",0));assertEquals(background.getPath(),ReadingProfiles.capture(w.app).getString("background_path"));}
    @Test public void customTitlePauseIsIndependentOfTheSourceText(){SpeechCursor cursor=new SpeechCursor();cursor.titlePause=4000;String original="Título isolado\n\nUma frase com pontuação.";cursor.load(original,0);SpeechCursor.Chunk heading=cursor.next(1200);assertEquals(4000,heading.pauseAfter);assertEquals("Título isolado",heading.text);assertEquals(original,cursor.text);}
    @Test public void readingPlanUsesTheStartingPositionAndDayAllowance()throws Exception{long day=86400000L;JSONObject plan=new JSONObject().put("total",100).put("per_day",10).put("start_unit",20).put("started",day*20);String first=ReadingPlan.status(plan,20,day*20);String next=ReadingPlan.status(plan,30,day*21);assertTrue(first.contains("21 / 30"));assertTrue(next.contains("31 / 40"));assertTrue(first.contains("Previsão"));}
}
